// SpecBoard がプロジェクト「見本」から作ったファイルです。書き換えはプロジェクトで
import { z } from "zod";

// オブジェクトは z.strictObject です。未知のフィールドは strip されず拒否されます
// （JSON Schema 出力の additionalProperties: false と一致させています）。

// 「未生成の rule」は、他文書を参照するか式を含むため、この生成器では検証コードに
// できないものです。コメントとしてのみ残しています。機械可読な定義が必要な場合は
// JSON Schema 出力の x-rules を参照してください。

/** 開いた列挙型: 未知の値も受け付ける。既知の値は StatusKnown */
export const StatusKnown = ["open", "paid", "shipped"] as const;
export const Status = z.string();
export type Status = z.infer<typeof Status>;

export const Line = z.strictObject({
  sku: z.string(),
  qty: z.int().optional(),
});
export type Line = z.infer<typeof Line>;

/** 注文 — 注文の記録 — 未生成の rule: sumOf(of=lines[].qty, into=total) — （未知の rule。記録のみ） — discount は意図的に持たない: 割引は別の文書で持つ */
export const Order = z.strictObject({
  // 主キー
  id: z.uuid(),
  // 税込み
  total: z.string(),
  status: Status.optional(),
  lines: z.array(Line).optional(),
  // Customer に存在する値
  customer_id: z.string().optional(),
  shipping: z.strictObject({
    // 一意
    postal_code: z.string().nullable().optional(),
  }).optional(),
  // 常に "order"
  kind: z.literal("order").optional(),
});
export type Order = z.infer<typeof Order>;

export const Customer = z.strictObject({
  // 主キー
  id: z.uuid().optional(),
  // 名前
  name: z.string().optional(),
});
export type Customer = z.infer<typeof Customer>;

/**
 * Rule
 *
 * 注文は Order.total を持つ。
 *
 * （図: Order）
 */
